#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include "h3api.h"
#include "polygon.h"
#include "polyfill.h"

void test_poly(LatLng *verts,int res){
 GeoPolygon p={.geoloop={.numVerts=4,.verts=verts},.numHoles=0,.holes=NULL};
 int64_t sz=0; H3Error e=maxPolygonToCellsSizeExperimental(&p,res,CONTAINMENT_OVERLAPPING,&sz);
 if(e||sz<0||sz>1000000) return;
 H3Index *out=calloc((sz?sz:1)+10000,sizeof(H3Index));
 H3Error e2=polygonToCellsExperimental(&p,res,CONTAINMENT_OVERLAPPING,out);
 int64_t cnt=0; while(cnt<sz+10000 && out[cnt]) cnt++;
 free(out);
 if(!e2 && cnt>sz){
  printf("FOUND res=%d sz=%ld cnt=%ld\n",res,(long)sz,(long)cnt);
  for(int i=0;i<4;i++) printf("%.17g %.17g\n",verts[i].lat,verts[i].lng);
  exit(0);
 }
}
int main(){
 for(int res=0;res<=5;res++){
   int64_t n; getNumCells(res,&n); if(n>20000) n=20000;
   H3Index *cells=calloc(n,sizeof(H3Index));
   if(res==0) getRes0Cells(cells); else {H3Index r0[122]; getRes0Cells(r0); int64_t idx=0; for(int b=0;b<122&&idx<n;b++){int64_t cs; cellToChildrenSize(r0[b],res,&cs); H3Index *ch=calloc(cs,sizeof(H3Index)); cellToChildren(r0[b],res,ch); for(int64_t k=0;k<cs&&idx<n;k++) if(ch[k]) cells[idx++]=ch[k]; free(ch);} n=idx;}
   fprintf(stderr,"res %d n %ld\n",res,(long)n);
   for(int64_t ci=0;ci<n;ci++){
    CellBoundary cb; if(cellToBoundary(cells[ci],&cb)) continue;
    for(int j=0;j<cb.numVerts;j++){
      LatLng a=cb.verts[j], b=cb.verts[(j+1)%cb.numVerts];
      double dx=b.lng-a.lng, dy=b.lat-a.lat; double L=hypot(dx,dy); if(L==0) continue;
      double nx=-dy/L, ny=dx/L;
      for(int wi=0;wi<8;wi++){
        double w=pow(10,-8+wi*0.5);
        for(int ei=0;ei<8;ei++){
          double ext=(ei-2)*0.02*L;
          LatLng v[4];
          v[0].lat=a.lat - dy*0.1 + ny*w; v[0].lng=a.lng - dx*0.1 + nx*w;
          v[1].lat=b.lat + dy*0.1 + ny*w; v[1].lng=b.lng + dx*0.1 + nx*w;
          v[2].lat=b.lat + dy*0.1 - ny*w; v[2].lng=b.lng + dx*0.1 - nx*w;
          v[3].lat=a.lat - dy*0.1 - ny*w; v[3].lng=a.lng - dx*0.1 - nx*w;
          test_poly(v,res);
        }
      }
    }
   }
   free(cells);
 }
 return 1;
}
